+function resourceMatches(resource: string, requestResource: string): boolean {
+  if (resource === "*") return true;
+  if (resource.endsWith("/*")) {
+    const prefix = resource.slice(0, -1);
+    return requestResource.startsWith(prefix);
+  }
+  return resource === requestResource;
+}
+
+function resourceSpecificity(resource: string, requestResource: string): number {
+  if (resource === "*") return 0;
+  if (resource.endsWith("/*")) return resource.length - 1;
+  return 1000 + resource.length;
+}
+
+function ruleSpecificity(rule: Rule, request: AccessRequest): number {
+  if (rule.role !== "*" && !request.roles.includes(rule.role)) return -1;
+  if (rule.action !== "*" && rule.action !== request.action) return -1;
+  if (!resourceMatches(rule.resource, request.resource)) return -1;
+  const rRole = rule.role === "*" ? 0 : 100;
+  const rAction = rule.action === "*" ? 0 : 100;
+  const rResource = resourceSpecificity(rule.resource, request.resource);
+  return rRole + rAction + rResource;
+}
